#include <stdint.h>
#include <string.h>

float vectorized_s3110(int iterations, float aa[256][256])
{
    int xindex, yindex;
    float max, chksum;

    for (int nl = 0; nl < 100*(iterations/(256)); nl++) {
        max = aa[0][0];
        xindex = 0;
        yindex = 0;

        for (int i = 0; i < 256; i++) {
            /* Vectorize inner loop: find max in row i with its index */
            float row_max = aa[i][0];
            int row_jmax = 0;

            /* Unroll by 8 for vector-friendly access */
            int j = 0;
            /* Process chunks of 8 */
            for (; j <= 256 - 8; j += 8) {
                float v0 = aa[i][j+0];
                float v1 = aa[i][j+1];
                float v2 = aa[i][j+2];
                float v3 = aa[i][j+3];
                float v4 = aa[i][j+4];
                float v5 = aa[i][j+5];
                float v6 = aa[i][j+6];
                float v7 = aa[i][j+7];

                if (v0 > row_max) { row_max = v0; row_jmax = j+0; }
                if (v1 > row_max) { row_max = v1; row_jmax = j+1; }
                if (v2 > row_max) { row_max = v2; row_jmax = j+2; }
                if (v3 > row_max) { row_max = v3; row_jmax = j+3; }
                if (v4 > row_max) { row_max = v4; row_jmax = j+4; }
                if (v5 > row_max) { row_max = v5; row_jmax = j+5; }
                if (v6 > row_max) { row_max = v6; row_jmax = j+6; }
                if (v7 > row_max) { row_max = v7; row_jmax = j+7; }
            }
            /* Scalar tail */
            for (; j < 256; j++) {
                if (aa[i][j] > row_max) {
                    row_max = aa[i][j];
                    row_jmax = j;
                }
            }

            if (row_max > max) {
                max = row_max;
                xindex = i;
                yindex = row_jmax;
            }
        }

        chksum = max + (float)xindex + (float)yindex;
    }

    return max + xindex + 1 + yindex + 1;
}
